def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        stack.append((nx,ny))
            comps.append(comp)

    out = [row[:] for row in grid]
    if comps:
        smallest = min(map(len, comps))
        largest = max(map(len, comps))
        for comp in comps:
            color = 7 if len(comp) == smallest else (8 if len(comp) == largest else None)
            if color is not None:
                for r, c in comp:
                    out[r][c] = color
    return out
